/** A module function minus its leading context parameter. */
export type Op<F> = F extends (bedit: BrandEditorCtx, ...a: infer A) => infer R ? (...a: A) => R : never;

/** Bind a module function to one context so it can be passed around as a value. */
export function bindOp<F extends (bedit: BrandEditorCtx, ...a: never[]) => unknown>(bedit: BrandEditorCtx, f: F): Op<F> {
  return ((...a: never[]) => f(bedit, ...a)) as Op<F>;
}
